import React, { useCallback, useEffect, useRef } from "react";
import { useRive, Layout, Fit, Alignment, RuntimeLoader } from "@rive-app/react-canvas";

RuntimeLoader.setWasmUrl("/animations/rive.wasm");
RuntimeLoader.setWasmFallbackUrl("/animations/rive_fallback.wasm");

// Loaded only in the browser by the illustration components.
export default function RiveAnimation({ src, artboard, stateMachine, animation, onReady, onError, onComplete, inkRef, inkState, active }) {
  const container = useRef(null);
  const started = useRef(false);
  const handlePlay = useCallback(() => { started.current = true; }, []);
  const handleStop = useCallback(() => {
    // Rive also emits stop while initializing; only finish a started animation.
    if (!started.current) return;
    started.current = false;
    onComplete?.();
  }, [onComplete]);
  const { rive, RiveComponent } = useRive({
    src,
    artboard,
    stateMachine,
    animations: animation,
    autoBind: Boolean(inkRef),
    autoplay: false,
    layout: new Layout({ fit: Fit.Contain, alignment: Alignment.Center }),
    onLoadError: onError,
    onPlay: animation ? handlePlay : undefined,
    onStop: animation ? handleStop : undefined,
  });

  useEffect(() => {
    if (!rive) return undefined;
    rive.resizeDrawingSurfaceToCanvas();
    onReady?.();
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    let visible = true;
    const sync = () => {
      if (motion.matches || document.hidden || !visible) rive.pause();
      else rive.play(animation || stateMachine);
    };
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      sync();
    });
    if (container.current) observer.observe(container.current);
    motion.addEventListener("change", sync);
    document.addEventListener("visibilitychange", sync);
    sync();
    return () => {
      observer.disconnect();
      motion.removeEventListener("change", sync);
      document.removeEventListener("visibilitychange", sync);
    };
  }, [rive, stateMachine, animation, onReady]);

  useEffect(() => {
    if (!rive || !inkRef) return undefined;
    const sync = () => {
      const rgb = getComputedStyle(inkRef.current).color.match(/[\d.]+/g);
      if (rgb) rive.viewModelInstance?.color("ink")?.rgb(...rgb.slice(0, 3).map(Number));
    };
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    return () => observer.disconnect();
  // Re-read inherited ink when the support key changes color, even while focused.
  }, [rive, inkRef, inkState, active]);

  return (
    <div ref={container} className="rive-animation" aria-hidden="true">
      <RiveComponent style={{ width: "100%", height: "100%" }} />
    </div>
  );
}
